class Solution {public String solve(String text,String pattern){if(pattern.length()==0)return "";int[] need=new int[26];for(char c:pattern.toCharArray())need[c-'a']++;int missing=pattern.length(),left=0,start=0,best=Integer.MAX_VALUE;for(int right=0;right<text.length();right++){int c=text.charAt(right)-'a';if(need[c]>0)missing--;need[c]--;while(missing==0){if(right-left+1<best){best=right-left+1;start=left;}int old=text.charAt(left++)-'a';if(++need[old]>0)missing++;}}return best==Integer.MAX_VALUE?"":text.substring(start,start+best);}}